package com.erpsystem.ops.actuator;

import com.erpsystem.ops.service.TenantCacheService;
import org.springframework.boot.actuate.endpoint.annotation.Endpoint;
import org.springframework.boot.actuate.endpoint.annotation.Selector;
import org.springframework.boot.actuate.endpoint.annotation.WriteOperation;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Component;

@Component
@Endpoint(id = "tenant-cache-manager")
public class TenantCacheActuatorEndpoint {

    private final TenantCacheService cacheService;

    public TenantCacheActuatorEndpoint(TenantCacheService cacheService) {
        this.cacheService = cacheService;
    }

    @WriteOperation
    public String purgeTenantCache(@Selector String tenantId, String cacheRegion) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (auth != null && auth.getPrincipal() instanceof Jwt jwt) {
            String callerTenant = jwt.getClaimAsString("tenantId");
            boolean isGlobalAdmin = auth.getAuthorities().stream().anyMatch(a -> a.getAuthority().equals("ROLE_GLOBAL_ADMIN"));
            if (!isGlobalAdmin && (callerTenant == null || !callerTenant.equals(tenantId))) {
                throw new AccessDeniedException("Cannot purge cache for a foreign tenant");
            }
        }
        cacheService.evictRegion(tenantId, cacheRegion);
        return "Purged cache " + cacheRegion + " for tenant " + tenantId;
    }
}
